function Y = depth_noise(Y0,pram,seed)
% EM conditional lookup tables are generated by the paper's Bernoulli register.
% Regenerate for the actual gain and extend instead of capping input counts.
% Both arms use the same deterministic table. Read noise is pixel independent.
rng(seed,'twister');
counts=poissrnd(double(Y0)+pram.cam_dXdt_dark*pram.cam_t_exp);
state=rng;
table=depth_emhist(pram,max(counts(:)));
rng(state);
Y=zeros(size(counts));
positive=find(counts>0);
if ~isempty(positive)
    draws=randi(size(table,2),size(positive));
    Y(positive)=table(sub2ind(size(table),counts(positive),draws));
end
Y=single((Y+pram.cam_sigma_rd*randn(size(Y)))/pram.cam_EMgain);
end
